namespace Dafeiyu.Tests {
 public static class UsageStatisticsUiTests {
  static int checks;
  static Assembly assembly=typeof(UsageStatisticsUiTests).Assembly;
  static void Check(bool condition,string message){if(!condition)throw new Exception(message);checks++;Console.WriteLine("PASS "+message);}
  static Type Find(string name){return assembly.GetType("Dafeiyu."+name);}
  static object Get(object value,string field){return value.GetType().GetField(field,BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic).GetValue(value);}
  static void Set(object value,string field,object setting){value.GetType().GetField(field).SetValue(value,setting);}
  static object Call(string method,params object[] values){return Find("UsageStatisticsModel").GetMethod(method,BindingFlags.Static|BindingFlags.Public|BindingFlags.NonPublic).Invoke(null,values);}
  static IList Records(){return (IList)Activator.CreateInstance(typeof(List<>).MakeGenericType(Find("UsageRecord")));}
  static object Record(string id,DateTime day,long? input,long? output,long? total,string feature,string conversation,string provider,bool estimated){var value=Activator.CreateInstance(Find("UsageRecord"));Set(value,"RequestId",id);Set(value,"TimestampUtc",day.ToUniversalTime());Set(value,"InputTokens",input);Set(value,"OutputTokens",output);Set(value,"TotalTokens",total);Set(value,"Feature",feature);Set(value,"ConversationId",conversation);Set(value,"Provider",provider);Set(value,"Model","model-a");Set(value,"Status","complete");Set(value,"IsEstimated",estimated);return value;}
  static IEnumerable<T> All<T>(DependencyObject root)where T:DependencyObject{if(root is T)yield return (T)root;for(int i=0;i<VisualTreeHelper.GetChildrenCount(root);i++)foreach(var x in All<T>(VisualTreeHelper.GetChild(root,i)))yield return x;}
  [STAThread]public static int Main(string[] args){try{
   Check(Find("UsageStatisticsModel")!=null,"usage statistics aggregation is implemented");
   var date=new DateTime(2026,10,18,12,0,0,DateTimeKind.Local);var records=Records();
   var first=Record("first",date,100,50,150,"chat","one","provider-a",false);Set(first,"CachedInputTokens",80L);Set(first,"ReasoningTokens",20L);records.Add(first);
   records.Add(Record("helper",date,20,10,30,"title","one","provider-a",true));records.Add(Record("unknown",date.AddDays(-1),null,null,null,"work","two","provider-b",false));records.Add(Record("zero",date.AddDays(-2),0,0,0,"review","two","provider-b",false));
   var summary=Call("Summarize",records);Check((long)Get(summary,"KnownTokens")==180,"cache and reasoning subsets do not inflate totals");Check((int)Get(summary,"Requests")==4&&(int)Get(summary,"UnknownRequests")==1&&(int)Get(summary,"EstimatedRequests")==1,"real zero, unknown and estimated requests stay distinct");
   var partial=Record("partial",date,20,null,null,"chat",null,null,false);Check(Call("EffectiveTotal",partial)==null,"a partial input count cannot masquerade as a total");
   var filtered=(IList)Call("Filter",records,"provider-a",null,null,null);Check(filtered.Count==2&&(long)Get(Call("Summarize",filtered),"KnownTokens")==180,"provider filtering includes attributed auxiliary requests once");
   var ranked=(IList)Call("Conversations",records);Check(ranked.Count==2&&(long)Get(ranked[0],"KnownTokens")==180&&(int)Get(ranked[0],"AuxiliaryRequests")==1,"conversation ranking and auxiliary attribution agree with totals");
   var unknownDay=Call("Day",records,date.AddDays(-1).Date);var zeroDay=Call("Day",records,date.AddDays(-2).Date);var missingDay=Call("Day",records,date.AddDays(-3).Date);Check((int)Get(unknownDay,"UnknownRequests")==1&&(int)Get(zeroDay,"Requests")==1&&(int)Get(missingDay,"Requests")==0,"daily cells distinguish unknown, measured zero and uncollected");
   string tooltip=(string)Call("Describe",unknownDay);Check(tooltip.Contains("未知")&&tooltip.Contains("2026-10-17"),"heatmap detail carries actual local date and unknown state");
   var week=Call("Between",records,date.AddDays(-6).Date,date.Date);Check((int)Get(week,"Requests")==4&&(long)Get(week,"KnownTokens")==180,"inclusive weekly range agrees with ranking");
   Check((string)Call("Total",Call("Summarize",Records()))=="—","empty history does not fabricate a zero Token total");
   Check((string)Call("Total",Call("Summarize",records))=="180 + 未知（含估算）","mixed source summary visibly states unknown and estimated totals");
   Set(first,"ProjectId","project-a");Check(((IList)Call("Filter",records,null,"model-a","project-a","chat")).Count==1,"model project and feature predicates combine without broadening scope");
   var midnight=Record("midnight",date.Date,1,1,2,"chat","midnight","provider-a",false);var midnightRows=Records();midnightRows.Add(midnight);Check((int)Get(Call("Day",midnightRows,date.Date),"Requests")==1&&(int)Get(Call("Day",midnightRows,date.Date.AddDays(-1)),"Requests")==0,"UTC storage is grouped by the actual local calendar day");
   var missingMetadata=Records();var missing=Record("missing-metadata",date,1,1,2,null,null,null,false);Set(missing,"Model",null);missingMetadata.Add(missing);Check(((IList)Call("Filter",missingMetadata,"","","","")).Count==1,"missing provider model and feature metadata can be selected honestly");
   Check((int)Get(Call("Summarize",missingMetadata),"AuxiliaryRequests")==0,"unclassified requests are not fabricated into auxiliary usage");
   var color=Find("UsageVisuals").GetMethod("GroupColor",BindingFlags.Static|BindingFlags.NonPublic);Check(new[]{"chat","work","subagent","review","prediction","title","compaction","greeting"}.Select(k=>color.Invoke(null,new object[]{k}).ToString()).Distinct().Count()==8,"the eight tracked features have distinct stable legend colors");
   Check(Find("UsageStatisticsModel").GetMethod("Calendar",BindingFlags.Static|BindingFlags.NonPublic)!=null,"calendar aggregation is implemented");var daily=(IList)Call("Calendar",records,date.Date.AddDays(-364),date.Date,0);var weekly=(IList)Call("Calendar",records,date.Date.AddDays(-364),date.Date,1);var cumulative=(IList)Call("Calendar",records,date.Date.AddDays(-364),date.Date,2);Check(daily.Count==365&&weekly.Count>=52&&weekly.Count<=54,"weekly heatmap contains one bucket per actual week");Check((long)Get(cumulative[cumulative.Count-1],"KnownTokens")==180&&(int)Get(cumulative[cumulative.Count-1],"UnknownRequests")==1,"cumulative calendar retains unknown records and counts each request once");
   var large=Records();for(int i=0;i<10000;i++)large.Add(Record("large-"+i,date.AddDays(-(i%365)),1,1,2,i%2==0?"chat":"title","bulk","provider-a",false));var largeCalendar=(IList)Call("Calendar",large,date.Date.AddDays(-364),date.Date,0);long largeTotal=0;foreach(var item in largeCalendar)largeTotal+=(long)Get(item,"KnownTokens");Check(largeTotal==20000&&(long)Get(Call("Summarize",large),"KnownTokens")==largeTotal,"ten thousand request calendar and summary totals agree");
   var ticksMethod=Find("UsageBarChart").GetMethod("TickIndices",BindingFlags.Static|BindingFlags.NonPublic);Check(ticksMethod!=null,"chart dates adapt to available width");var ticks=(IList<int>)ticksMethod.Invoke(null,new object[]{30,214d});Check(ticks.Count<=4&&ticks[0]==0&&ticks[ticks.Count-1]==29,"narrow charts retain first and last dates with readable spacing");
   Check(Find("UsageStatisticsModel").GetMethod("HeatDetail",BindingFlags.Static|BindingFlags.NonPublic)!=null,"heatmap details define each selected aggregation mode");var dayDetail=Call("HeatDetail",Call("Day",records,date.Date),0,date.Date.AddDays(-364),date.Date);Check((string)Get(dayDetail,"Title")=="2026年10月18日"&&((string)Get(dayDetail,"Value")).Contains("当日 180 Token")&&((string)Get(dayDetail,"Value")).Contains("含估算"),"daily detail identifies the real date amount and estimated source");var weekDetail=Call("HeatDetail",weekly[weekly.Count-1],1,date.Date.AddDays(-364),date.Date);Check(((string)Get(weekDetail,"Title")).Contains("2026年10月12日")&&((string)Get(weekDetail,"Title")).Contains("2026年10月18日")&&((string)Get(weekDetail,"Value")).Contains("周合计"),"weekly detail names its actual range and weekly total");var cumulativeDetail=Call("HeatDetail",cumulative[cumulative.Count-1],2,date.Date.AddDays(-364),date.Date);Check((string)Get(cumulativeDetail,"Title")=="累计至 2026年10月18日"&&((string)Get(cumulativeDetail,"Value")).Contains("自 2025.10.19 起")&&((string)Get(cumulativeDetail,"Value")).Contains("未知"),"cumulative detail states its cutoff origin and unknown remainder");var emptyDetail=Call("HeatDetail",Call("Day",records,date.AddDays(-3).Date),0,date.Date.AddDays(-364),date.Date);Check((string)Get(emptyDetail,"Value")=="当日未采集","uncollected detail avoids an invented zero");
   if(!args.Contains("--headless"))Ui(records);
   Console.WriteLine("Usage statistics tests: "+checks+" passed");return 0;
  }catch(Exception error){Console.WriteLine("FAIL "+error);return 1;}}
  static void Ui(IList records){
   string folder=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"usage-ui-"+Guid.NewGuid().ToString("N"));var store=Activator.CreateInstance(Find("UsageStore"),new object[]{folder});foreach(var row in records)Find("UsageStore").GetMethod("AddOrUpdate").Invoke(store,new[]{row});
   var page=(UserControl)Activator.CreateInstance(Find("UsageStatisticsPage"),new[]{store});var window=new Window{Title="用量统计 · 自有样本验收",Width=1040,Height=900,Content=page,WindowStartupLocation=WindowStartupLocation.CenterScreen};
   try{window.Show();Pump();
    Check(page is IDisposable,"usage page supports deterministic event cleanup");
    Check(All<TextBlock>(page).Any(t=>t.Text=="用量统计"),"independent page shows Chinese heading");
    Check(All<TextBlock>(page).Any(t=>t.Text.Contains("文字模型")&&t.Text.Contains("ASR")&&t.Text.Contains("TTS")&&t.Text.Contains("Live")),"page scope explicitly excludes untracked audio services");
    Check(All<ComboBox>(page).Count()==5,"provider model project feature and heatmap mode controls are present");
    var cells=All<Button>(page).Where(b=>b.Name=="UsageHeatCell").ToList();Check(cells.Count>=365&&cells.Any(b=>b.ToolTip!=null),"year heatmap exposes actual tooltips on keyboard-focusable cells");
    var heatGrid=(Grid)VisualTreeHelper.GetParent(cells[0]);var padding=heatGrid.Children.OfType<Border>().Where(b=>b.Name=="UsageHeatPadding").ToList();Check(cells.Count==365&&cells.Count+padding.Count==heatGrid.ColumnDefinitions.Count*7,"daily heatmap fills complete week columns without adding fabricated date buttons");Check(padding.All(b=>b.Tag is DateTime&&((DateTime)b.Tag<DateTime.Today.AddDays(-364)||(DateTime)b.Tag>DateTime.Today)&&!b.Focusable),"calendar padding only covers dates outside the measured interval and cannot be selected");
    cells.Last().Focus();Pump();var focusedTip=(ToolTip)cells.Last().ToolTip;Check(focusedTip.IsOpen,"keyboard focus opens the same actual cell detail as pointer hover");var tipSurface=(Border)focusedTip.Content;Check(((SolidColorBrush)tipSurface.Background).Color==Color.FromRgb(36,38,43)&&tipSurface.CornerRadius.TopLeft==8&&All<TextBlock>(tipSurface).Count()==2,"heatmap tooltip uses one dark rounded surface and exactly two white text lines");Check(All<TextBlock>(tipSurface).All(t=>((SolidColorBrush)t.Foreground).Color.R>=220),"heatmap tooltip text stays readable on the dark surface");Save(tipSurface,"usage-heat-tooltip-daily-fixture.png");
    Save(page,"usage-overview-fixture.png");
    var providerFilter=All<ComboBox>(page).Single(c=>c.Name=="UsageProviderFilter");var projectFilter=All<ComboBox>(page).Single(c=>c.Name=="UsageProjectFilter");var featureFilter=All<ComboBox>(page).Single(c=>c.Name=="UsageFeatureFilter");providerFilter.SelectedItem=providerFilter.Items.OfType<ComboBoxItem>().Single(c=>(string)c.Tag=="provider-a");Pump();Check(Metric(page,"请求次数")=="2","changing the provider control filters the visible request count");projectFilter.SelectedItem=projectFilter.Items.OfType<ComboBoxItem>().Single(c=>(string)c.Tag=="project-a");Pump();Check(Metric(page,"请求次数")=="1","project selection combines with the visible provider filter");featureFilter.SelectedItem=featureFilter.Items.OfType<ComboBoxItem>().Single(c=>(string)c.Tag=="title");Pump();Check(Metric(page,"请求次数")=="0"&&Metric(page,"累计 Token")=="—","empty combined filters show an honest empty Token state");providerFilter.SelectedIndex=0;projectFilter.SelectedIndex=0;featureFilter.SelectedIndex=0;Pump();
    var mode=All<ComboBox>(page).Single(c=>c.Name=="UsageHeatMode");mode.SelectedIndex=1;Pump();Check(All<Button>(page).Count(b=>b.Name=="UsageHeatCell")<=54,"weekly selection displays actual weekly buckets");var weekCell=All<Button>(page).Where(b=>b.Name=="UsageHeatCell").Last();weekCell.RaiseEvent(new MouseEventArgs(Mouse.PrimaryDevice,0){RoutedEvent=Mouse.MouseEnterEvent});Pump();var weekTip=(ToolTip)weekCell.ToolTip;Check(weekTip.IsOpen&&All<TextBlock>((Border)weekTip.Content).Any(t=>t.Text.Contains("周合计")),"pointer hover opens the same themed tooltip with an actual weekly total");Save((Border)weekTip.Content,"usage-heat-tooltip-weekly-fixture.png");weekCell.RaiseEvent(new MouseEventArgs(Mouse.PrimaryDevice,0){RoutedEvent=Mouse.MouseLeaveEvent});Check(!weekTip.IsOpen,"leaving a heatmap cell closes its tooltip");mode.SelectedIndex=2;Pump();Check(All<Button>(page).Count(b=>b.Name=="UsageHeatCell")==365,"cumulative selection restores daily dates");var cumulativeCell=All<Button>(page).Where(b=>b.Name=="UsageHeatCell").Last();cumulativeCell.Focus();Pump();var cumulativeTip=(ToolTip)cumulativeCell.ToolTip;Check(All<TextBlock>((Border)cumulativeTip.Content).Any(t=>t.Text.StartsWith("累计至 "))&&All<TextBlock>((Border)cumulativeTip.Content).Any(t=>t.Text.StartsWith("自 ")),"visible cumulative detail explicitly identifies cutoff and starting date");Save((Border)cumulativeTip.Content,"usage-heat-tooltip-cumulative-fixture.png");mode.SelectedIndex=0;Pump();All<Button>(page).Where(b=>b.Name=="UsageHeatCell").Last().RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Pump();Check(All<TextBlock>(page).Single(t=>t.Name=="UsagePeriodLabel").Text.Contains(DateTime.Today.ToString("yyyy-MM-dd")),"clicking a heatmap date opens the matching analysis interval");
    var analysis=All<Button>(page).Single(b=>b.Name=="UsageAnalysisTab");analysis.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));page.UpdateLayout();
    Check(All<Button>(page).Any(b=>b.Name=="UsageSevenDays")&&All<Button>(page).Any(b=>b.Name=="UsageThirtyDays"),"analysis exposes working seven and thirty day intervals");
    var period=All<TextBlock>(page).Single(t=>t.Name=="UsagePeriodLabel");string before=period.Text;All<Button>(page).Single(b=>b.Name=="UsagePreviousPeriod").RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Check(before!=period.Text,"previous time range changes analysis dates");
    All<Button>(page).Single(b=>b.Name=="UsageNextPeriod").RaiseEvent(new RoutedEventArgs(Button.ClickEvent));All<Button>(page).Single(b=>b.Name=="UsageThirtyDays").RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Pump();Save(page,"usage-analysis-fixture.png");
    var conversation=All<Expander>(page).First();conversation.IsExpanded=true;Pump();Check(All<TextBlock>(conversation).Any(t=>t.IsVisible&&t.Text.Contains("输入 120")&&t.Text.Contains("输出 60"))&&All<TextBlock>(conversation).Any(t=>t.IsVisible&&t.Text.Contains("辅助请求 1 次")),"expanded conversation shows measured input output and attributed helper count");
    window.Width=370;Pump();Check(page.ActualWidth<=370&&page.DesiredSize.Width<=370,"usage page measures within narrow host");var provider=All<ComboBox>(page).Single(c=>c.Name=="UsageProviderFilter");var model=All<ComboBox>(page).Single(c=>c.Name=="UsageModelFilter");Check(Math.Abs(provider.TranslatePoint(new Point(),page).Y-model.TranslatePoint(new Point(),page).Y)<1,"narrow filters retain two usable columns");Save(page,"usage-narrow-fixture.png");var scroll=All<ScrollViewer>(page).First();scroll.ScrollToEnd();Pump();Save(page,"usage-narrow-detail-fixture.png");
    WarningUi(window,folder,records[0]);
   }finally{window.Close();((IDisposable)page).Dispose();string testRoot=Path.GetFullPath(AppDomain.CurrentDomain.BaseDirectory);if(Path.GetFullPath(folder).StartsWith(testRoot,StringComparison.OrdinalIgnoreCase))Directory.Delete(folder,true);}
  }
  static void WarningUi(Window window,string folder,object record){string blocked=Path.Combine(folder,"blocked-directory");File.WriteAllText(blocked,"fixture");var store=Activator.CreateInstance(Find("UsageStore"),new object[]{blocked});Find("UsageStore").GetMethod("AddOrUpdate").Invoke(store,new[]{record});var page=(UserControl)Activator.CreateInstance(Find("UsageStatisticsPage"),new[]{store});object original=window.Content;try{window.Content=page;Pump();var warning=All<TextBlock>(page).Single(t=>t.Name=="UsageStorageWarning");Check(warning.IsVisible&&warning.Text.Contains("内存"),"storage failure explains that visible current records are retained in memory");File.Delete(blocked);Find("UsageStore").GetMethod("AddOrUpdate").Invoke(store,new[]{record});Pump();Pump();Pump();Check(warning.Visibility==Visibility.Collapsed,"successful retry clears the visible storage warning through ledger notifications");}finally{window.Content=original;((IDisposable)page).Dispose();}}
  static string Metric(DependencyObject page,string label){var heading=All<TextBlock>(page).Single(t=>t.Text==label);var panel=(StackPanel)VisualTreeHelper.GetParent(heading);return panel.Children.OfType<TextBlock>().Skip(1).First().Text;}
  static void Pump(){var frame=new DispatcherFrame();var timer=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(100)};timer.Tick+=delegate{timer.Stop();frame.Continue=false;};timer.Start();Dispatcher.PushFrame(frame);}
  static void Save(FrameworkElement element,string name){var bitmap=new RenderTargetBitmap((int)Math.Ceiling(element.ActualWidth),(int)Math.Ceiling(element.ActualHeight),96,96,PixelFormats.Pbgra32);bitmap.Render(element);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(bitmap));using(var output=File.Create(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,name)))encoder.Save(output);}
 }
}
